#!/usr/bin/env python3
"""Build the public newsletter archive; no external dependencies or network calls."""
from pathlib import Path
import json,html
from dashboard_view import render as render_dashboard
R=Path(__file__).resolve().parents[1];D=R/'docs';D.mkdir(exist_ok=True);E=html.escape
weeks=sorted([json.loads(p.read_text()) for p in (R/'data').glob('week-*.json')],key=lambda w:w['week'],reverse=True)
def wrap(title,body,prefix=''):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Weekly fantasy football scoring, trends and matchup analysis for roblox and friends."><title>{E(title)} · roblox &amp; friends</title><link rel="stylesheet" href="{prefix}assets/style.css"></head><body><a class="skip" href="#main">Skip to content</a><header class="site-header"><a class="brand" href="{prefix}index.html">roblox <span>&amp;</span> friends</a><nav aria-label="Main navigation"><a href="{prefix}index.html">League</a><a href="{prefix}reports/2026/week-09.html">Reports</a></nav></header><main id="main">{body}</main><footer><span>Commissioner’s statistical review · 2026 season</span><a href="{prefix}methodology.html">Sources &amp; model notes</a></footer></body></html>'''
def scores(w):
 rows=''
 for m in w['matchups']:
  a=next(t for t in m['teams'] if t['roster_id']==m['winner_id']);b=next(t for t in m['teams'] if t['roster_id']!=m['winner_id']);name=lambda x:'Alexis' if x.startswith('alexis') else x
  rows+=f'<tr><td>{E(name(a["name"]))}</td><td>{E(name(b["name"]))}</td><td class="num">{a["points"]:.2f}–{b["points"]:.2f}</td><td class="num">{m["margin"]:.2f}</td></tr>'
 return '<div class="table"><table><caption>Final matchup results</caption><thead><tr><th>Winner</th><th>Opponent</th><th>Final score</th><th>Margin</th></tr></thead><tbody>'+rows+'</tbody></table></div>'
dashboard=json.loads((R/'data/dashboard.json').read_text())
(D/'index.html').write_text(wrap('League at a glance',render_dashboard(dashboard)))
for w in weeks:
 n=w['week'];content=(R/f'content/week-{n:02}.html').read_text();page=f'''<article><a class="back" href="../../index.html">← League overview</a><header class="report-header"><p class="eyebrow">2026 SEASON · WEEK {n}</p><h1>Week {n}<br>statistical review.</h1><p class="lead">Final scores, week-over-week trends and pivotal-play analysis.</p></header><section class="panel">{scores(w)}</section><div class="article-content">{content}</div><section><h2>Annotated matchup timelines</h2><p class="note">Tap the image to open it at full resolution. Idle gaps are compressed; real event times are retained. Changes show modeled scoring-only effects in percentage points.</p><a href="../../assets/week-{n:02}.png"><img class="graph" src="../../assets/week-{n:02}.png" alt="Four Week {n} matchup probability graphs, annotated with pivotal plays and compressed idle periods" loading="lazy"></a></section><aside class="model-note"><strong>About these estimates</strong><p>Probabilities are experimental estimates, not Sleeper’s archived live percentages. Projection history, injuries, correlations and late-game uncertainty remain approximate.</p><a href="../../methodology.html">Full methodology and sources →</a></aside><nav class="week-nav" aria-label="Weekly reports">'''+''.join(f'<a href="week-{x["week"]:02}.html">Week {x["week"]}</a>' for x in weeks)+'''</nav></article>'''
 target=D/f'reports/2026/week-{n:02}.html';target.parent.mkdir(parents=True,exist_ok=True);target.write_text(wrap(f'Week {n}',page,'../../'))
method='''<article><a class="back" href="index.html">← League overview</a><header class="report-header"><p class="eyebrow">TRANSPARENT BY DESIGN</p><h1>How the reports<br>are calculated.</h1></header><div class="article-content"><h2>Actual scores and effective lineups</h2><p>League scoring settings, weekly lineups and final points come from Sleeper.</p><h2>Scoring trends</h2><p>Week-over-week changes compare final team totals. Weekly ranks compare the eight teams. All-play records compare each team with all seven opponents each week. A 200-point week or scoring streak describes observed results, not future performance.</p><h2>Projected finishing scores</h2><p>At each timestamp: actual points plus the projected points still to come. Future NFL games retain their baseline; remaining projections decline with regulation game-clock time. Sleeper’s projected stats are rescored under this league’s rules. Missing custom defense counters use prior team history, shrunk toward the NFL league average.</p><h2>Experimental win probabilities</h2><p>Position-level uncertainty is fitted to prior-week projection errors. The primary model assumes independent Gaussian remaining-score errors, with variance declining with regulation time. It computes the chance one final score exceeds the other.</p><p>Shading changes uncertainty by ±20% and tests a chosen same-game correlation scenario. It is an assumption-sensitivity range, not a calibrated confidence interval.</p><h2>Pivotal-play labels</h2><p>We compare the post-play probability with a same-clock counterfactual removing that play’s net fantasy scoring. Clock and uncertainty stay fixed, and contributions to both fantasy teams on the same NFL play are combined. These percentage-point effects are not two consecutive historical live readings.</p><h2>Timeline display</h2><p>NFL game windows retain proportional real-time spacing. Gaps without any NFL games are shortened to narrow, hatched bands. Labels retain actual Pacific event times. The three largest absolute scoring effects per matchup are annotated.</p><h2>Limitations</h2><ul><li>Historical projection versions are not verified pre-kickoff archives. Effective lineups are held fixed retrospectively.</li><li>Injury exits, inactive status, possession and changing usage are not reconstructed.</li><li>Correlations are not learned, and defense thresholds are not simulated structurally.</li><li>Gaussian tails can allow implausible negative remaining contributions and distort late-game odds.</li><li>The model is not calibrated for precise historical live odds; use it for cautious comparisons and candidate pivotal moments.</li></ul><h2>Sources and attribution</h2><ul><li><a href="https://docs.sleeper.com/">Sleeper API</a>: league settings, matchup points, rosters and player metadata. Weekly stats and projections use undocumented endpoints.</li><li><a href="https://github.com/nflverse/nflverse-data">nflverse / nflfastR</a>: processed play-by-play, with raw NFL game data used when a cleaned game was not yet available. Data attribution: CC BY 4.0.</li><li><a href="https://github.com/dynastyprocess/data">DynastyProcess / ffverse</a>: cross-platform player IDs.</li></ul><p>Reports are snapshots and may change after stat corrections. No visitor account, live data collection or backend is required.</p></div></article>'''
method=method.replace('<h2>Sources and attribution</h2>', '''<h2 id="season-forecasts">League dashboard forecasts</h2><p>The dashboard is a frozen snapshot after Week 9. Standings use Sleeper’s record, points for and points against. Default standings ties break by record, points for, then higher points against; any remaining exact tie is random. Commissioner overrides are not modeled.</p><p>Week 10 lineups maximize the sum of league-scored Sleeper projections over QB, two RBs, three WRs, TE, three RB/WR/TE flexes, K and DEF. Each player can fill only one eligible slot. Current Out/IR designations and reserve status exclude players for Week 10. Questionable players are allowed. Missing projections, byes and unfilled slots contribute zero; the model does not add free agents.</p><p>Weeks 11–17 use each week’s Sleeper projections and re-optimize current rosters. Players with forecasts can return or be activated from reserve in those future weeks. This simplifying recovery assumption is not a medical forecast. No future injury process, waiver moves or trades are simulated. Custom defense categories missing from projections use Weeks 1–9 history shrunk toward the NFL mean.</p><p>For each selected player, score variance equals the position’s squared scaled RMSE from Weeks 1–8 times max(projected points, 3). Lineup variances are summed. Week 10 matchup odds use the normal distribution of the projected score difference. These odds and season simulations share the same score model; player and weekly outcomes are assumed independent.</p><p>100,000 fixed-seed simulations draw weekly team scores for Weeks 10–17. Weeks 10–14 follow the actual league schedule and add simulated wins, points for and points against. The top six seeds qualify, the top two receive Week 15 byes, seed 1 faces the 4/5 winner in Week 16 and seed 2 the 3/6 winner. Week 17 determines the champion. Exact playoff score ties favor the higher seed. Percentages near zero or one reflect simulated frequency, not mathematical elimination or clinching. Monte Carlo error is at most about 0.16 percentage points at one standard error; model uncertainty is larger.</p><p><a href="https://support.sleeper.com/en/articles/2203518-how-do-playoff-teams-get-determined">Sleeper’s default playoff seeding rules</a>. League settings specify six teams, Week 15 start and one-week rounds; the current bracket confirms the fixed semifinal paths. The homepage forecast snapshot timestamp identifies when source projections and rosters were retrieved. Publishing a code change does not fetch fresh league data.</p><h2>Sources and attribution</h2>''')
(D/'methodology.html').write_text(wrap('Methodology',method));(D/'.nojekyll').touch();print('Built',len(weeks),'weekly reports plus homepage and methodology')
